import hashlib,json,sys
from pathlib import Path
sys.path.insert(0,'tools')
import accept
sha=lambda path: hashlib.sha256(path.read_bytes()).hexdigest()
history=accept.read_history()
last=history[-1]
ledger=accept.load_json(accept.MATCHES)
expected=last['sources']
current_sources={unit['source'] for unit in ledger['units']}
failures=[]
for source in sorted(current_sources|set(expected)):
    path=accept.ROOT/source
    actual=sha(path) if path.is_file() else None
    if source not in expected:
        failures.append({'kind':'unexpected_unit','path':source})
    elif source not in current_sources:
        failures.append({'kind':'absent_unit','path':source})
    elif actual!=expected[source]:
        failures.append({'kind':'missing_source' if actual is None else 'changed_source','path':source,'expected_sha256':expected[source],'actual_sha256':actual})
headers=accept.header_hashes()
for name,expected_sha in sorted(last.get('headers',{}).items()):
    if headers.get(name)!=expected_sha:
        failures.append({'kind':'missing_header' if name not in headers else 'changed_header','path':name,'expected_sha256':expected_sha,'actual_sha256':headers.get(name)})
if sha(accept.MATCHES)!=last['matches_sha256']:
    failures.append({'kind':'ledger_hash','path':'config/matches.json'})
bindings={}
for entry in history:
    checkpoint=entry['checkpoint']
    base=accept.ROOT/'accept'/checkpoint
    for relative in ('prepare.json','finalize.json','matches.json',f'receipts/{checkpoint}-a.json',f'receipts/{checkpoint}-b.json'):
        bindings[f'accept/{checkpoint}/{relative}']=sha(base/relative)
print(json.dumps({'scope':'Complete live source/header/unit/ledger prerequisite failure inventory; does not claim that expected prepared-state failures are verification success. CLI independently checks receipt/history closure before its first live-source error.','checkpoints':len(history),'latest_checkpoint':last['checkpoint'],'history_sha256':sha(accept.HISTORY),'receipt_and_record_sha256':bindings,'failure_set':failures,'failure_count':len(failures)},sort_keys=True))

